#include <iostream>
#include <fstream>
int main() {
    {
        std::ofstream out("nums.txt");
        out << "1 2 3 4 5\n";
    }
    std::ifstream in("nums.txt");
    int x, sum = 0;
    while (in >> x) sum += x;        // 正确：提取成功才累加
    std::cout << "sum=" << sum << " eof=" << in.eof() << '\n';
}
